"""NPCI UPI AutoPay & Refund Webhook Handler (SEC-STD-02 compliant)."""

from dataclasses import dataclass
import hashlib
import hmac


@dataclass(frozen=True)
class WebhookResult:
    accepted: bool
    reason: str
    refund_id: str | None = None


def _mask_vpa(vpa: object) -> str:
    """Mask a UPI VPA for DPDP Act 2023 compliance (e.g. ra***@okicici)."""
    s = "" if vpa is None else str(vpa)
    if "@" in s:
        local, _, handle = s.partition("@")
        prefix = local[:2] if len(local) > 2 else local[:1]
        return f"{prefix}***@{handle}"
    prefix = s[:2] if len(s) > 2 else s[:1]
    return f"{prefix}***"


def _mask_mobile(mobile: object) -> str:
    """Mask a mobile number, showing only the last 4 digits."""
    s = "" if mobile is None else str(mobile)
    digits = "".join(ch for ch in s if ch.isdigit())
    if not digits:
        return "******"
    tail = digits[-4:]
    return "*" * 6 + tail


def _normalize_signature(signature_header: object) -> str | None:
    """Strip whitespace, drop optional 'sha256=' prefix, lowercase. None if invalid."""
    if not isinstance(signature_header, str):
        return None
    sig = signature_header.strip()
    if sig[:7].lower() == "sha256=":
        sig = sig[7:]
    sig = sig.strip().lower()
    if not sig or not sig.isascii():
        return None
    return sig


class UpiWebhookProcessor:
    def __init__(self, webhook_secret: str, replay_window_seconds: int = 300) -> None:
        self.webhook_secret = webhook_secret
        self.replay_window_seconds = replay_window_seconds
        self.processed_events: set[str] = set()
        self.refund_ledger: list[dict[str, object]] = []
        self.audit_log: list[str] = []

    def _audit(
        self,
        outcome: str,
        event_id: object,
        payer_vpa: object,
        mobile: object,
        timestamp: object,
    ) -> None:
        # Only masked PII is ever written to the audit log.
        self.audit_log.append(
            f"{outcome} event={event_id} vpa={_mask_vpa(payer_vpa)} "
            f"mobile={_mask_mobile(mobile)} ts={timestamp}"
        )

    def verify_and_process(
        self,
        *,
        event_id: str,
        raw_body: str,
        signature_header: str,
        timestamp: int,
        now_ts: int,
        payer_vpa: str,
        mobile: str,
        amount_paise: int,
    ) -> WebhookResult:
        # 1. Basic input validation (empty / invalid input).
        if (
            not isinstance(event_id, str)
            or not event_id
            or not isinstance(raw_body, str)
            or not isinstance(signature_header, str)
        ):
            self._audit("reject:INVALID_INPUT", event_id, payer_vpa, mobile, timestamp)
            return WebhookResult(accepted=False, reason="INVALID_INPUT", refund_id=None)

        try:
            ts_int = int(timestamp)
            now_int = int(now_ts)
        except (TypeError, ValueError):
            self._audit("reject:INVALID_INPUT", event_id, payer_vpa, mobile, timestamp)
            return WebhookResult(accepted=False, reason="INVALID_INPUT", refund_id=None)

        # 2. Symmetric replay window: rejects stale AND future-dated timestamps.
        if abs(now_int - ts_int) > self.replay_window_seconds:
            self._audit(
                "reject:STALE_OR_FUTURE_TIMESTAMP", event_id, payer_vpa, mobile, ts_int
            )
            return WebhookResult(
                accepted=False, reason="STALE_OR_FUTURE_TIMESTAMP", refund_id=None
            )

        # 3. HMAC-SHA256 over "{timestamp}.{raw_body}", constant-time comparison.
        provided = _normalize_signature(signature_header)
        canonical = f"{ts_int}.{raw_body}"
        expected = hmac.new(
            self.webhook_secret.encode("utf-8"),
            canonical.encode("utf-8"),
            hashlib.sha256,
        ).hexdigest()
        if provided is None or not hmac.compare_digest(expected, provided):
            self._audit("reject:INVALID_SIGNATURE", event_id, payer_vpa, mobile, ts_int)
            return WebhookResult(
                accepted=False, reason="INVALID_SIGNATURE", refund_id=None
            )

        # 4. Positive paise amount.
        try:
            amount_int = int(amount_paise)
        except (TypeError, ValueError):
            amount_int = 0
        if amount_int <= 0:
            self._audit("reject:INVALID_AMOUNT", event_id, payer_vpa, mobile, ts_int)
            return WebhookResult(accepted=False, reason="INVALID_AMOUNT", refund_id=None)

        # 5. event_id idempotency: never double-refund.
        if event_id in self.processed_events:
            self._audit(
                "reject:DUPLICATE_EVENT_REPLAY", event_id, payer_vpa, mobile, ts_int
            )
            return WebhookResult(
                accepted=False, reason="DUPLICATE_EVENT_REPLAY", refund_id=None
            )

        # All checks passed: record exactly one masked ledger row.
        refund_id = f"REF-{event_id}"
        self.processed_events.add(event_id)
        self.refund_ledger.append(
            {
                "event_id": event_id,
                "refund_id": refund_id,
                "amount_paise": amount_int,
                "payer_vpa": _mask_vpa(payer_vpa),
                "mobile": _mask_mobile(mobile),
            }
        )
        self._audit("accept:PROCESSED", event_id, payer_vpa, mobile, ts_int)
        return WebhookResult(accepted=True, reason="PROCESSED", refund_id=refund_id)

